import{_ as d,o as a,c as r,a2 as h}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"拡張設定提案リスト","description":"","frontmatter":{},"headers":[],"relativePath":"ja/0098-扩展设定建议清单.md","filePath":"ja/0098-扩展设定建议清单.md"}'),e={name:"ja/0098-扩展设定建议清单.md"};function o(l,t,i,n,b,s){return a(),r("div",null,[...t[0]||(t[0]=[h('<h1 id="拡張設定提案リスト" tabindex="-1">拡張設定提案リスト <a class="header-anchor" href="#拡張設定提案リスト" aria-label="Permalink to &quot;拡張設定提案リスト&quot;">​</a></h1><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>文書番号</td><td>98</td></tr><tr><td>モジュール</td><td>付録と参考資料</td></tr><tr><td>キーワード</td><td>拡張設定、創作提案、設定の方向性、開放性、未開発分野</td></tr></tbody></table><h2 id="_1-説明" tabindex="-1">1. 説明 <a class="header-anchor" href="#_1-説明" aria-label="Permalink to &quot;1. 説明&quot;">​</a></h2><p>本文書は、アンカー共生文明設定体系における拡張創作のための方向性と提案をリストアップしたものであり、設定創作者にインスピレーションとガイダンスを提供し、既存の枠組みの中で価値のある設定拡張を行うのを支援することを目的とする。本リストはモジュール別に分類されており、各拡張方向には方向の説明、拡張の価値、既存設定との関連、創作提案が含まれている。強調すべきは、本リストはあくまで提案的な参考であり、創作者は設定の一貫性を遵守する前提で自由に創作でき、また本リストに含まれていない全く新しい方向を開発することもできる。すべての拡張設定は、正式に組み込まれる前に文書97「設定矛盾自己チェック表」の検査に合格しなければならない。</p><h2 id="_2-世界観とコア設定の拡張方向" tabindex="-1">2. 世界観とコア設定の拡張方向 <a class="header-anchor" href="#_2-世界観とコア設定の拡張方向" aria-label="Permalink to &quot;2. 世界観とコア設定の拡張方向&quot;">​</a></h2><table tabindex="0"><thead><tr><th>番号</th><th>拡張方向</th><th>拡張の価値</th><th>関連設定</th><th>創作提案</th></tr></thead><tbody><tr><td>E01</td><td>宇宙の境界の外の存在</td><td>衡元宙の法則ネットワークの外に他の宇宙やより高い次元の存在があるかどうかを探求し、設定により壮大な宇宙観を提供する</td><td>文書00、文書28</td><td>「宇宙の壁」の存在や、宇宙の壁を突破した少数の探検家の物語を設定し、今後の宇宙間交流の伏線を残すことができる</td></tr><tr><td>E02</td><td>宇宙意志の本質</td><td>法則ネットワークの底層に何らかの「宇宙意志」が存在するかどうか、およびそれとアンカーメカニズムの関係を深く掘り下げる</td><td>文書00、文書20</td><td>宇宙意志を人格化されていない法則の自己組織化現象として設定し、特定の神としてではなく、「現実を基とする」立場を維持することができる</td></tr><tr><td>E03</td><td>前アンカー時代の失われた文明</td><td>前アンカー時代にかつて栄えたが消滅した文明を詳細に設定し、歴史の深みを豊かにする</td><td>文書71、文書93</td><td>代表的な3-5つの失われた文明を設定し、各文明に独自の修練体系、文化、消滅の原因を持たせ、考古学設定の素材を提供することができる</td></tr><tr><td>E04</td><td>共生理念の哲学流派</td><td>「反略奪、共生を提唱」の大枠の下で、異なる哲学流派が共生理念に対して異なる解釈を行うよう設定する</td><td>文書04、文書03</td><td>「過激共生派」「穏健共生派」「生態共生派」「技術共生派」などの流派を設定し、それらの間の思想的対立を重要なプロットの張力とすることができる</td></tr></tbody></table><h2 id="_3-修練体系の拡張方向" tabindex="-1">3. 修練体系の拡張方向 <a class="header-anchor" href="#_3-修練体系の拡張方向" aria-label="Permalink to &quot;3. 修練体系の拡張方向&quot;">​</a></h2><table tabindex="0"><thead><tr><th>番号</th><th>拡張方向</th><th>拡張の価値</th><th>関連設定</th><th>創作提案</th></tr></thead><tbody><tr><td>E05</td><td>単一体系の詳細な法門</td><td>三百套の体系のうちの一つを詳細に展開し、具体的な修練法門、境界突破の方法、よくある誤りなどを含める</td><td>文書10-19、文書91</td><td>本源三基および応用工程類の中で技術と密接に結びついた体系を優先的に展開することを推奨する。各体系の詳細文書には修練のステップ、心法の口訣、資源の需要、リスク警告などを含めることができる</td></tr><tr><td>E06</td><td>体系兼修の組み合わせ方案</td><td>異なる体系間の兼修の互換性を研究し、最適な多体系組み合わせ方案を設計する</td><td>文書10、文書11-13</td><td>「黄金の組み合わせ」（推演迭代+空間法理+応用工程）や各種の偏門の組み合わせを設定し、各組み合わせの優位性と限界を分析することができる</td></tr><tr><td>E07</td><td>修練のボトルネックと突破方法</td><td>各体系が異なる境界で遭遇する可能性のあるボトルネックと、ボトルネックを突破する複数の方法を詳細に設定する</td><td>文書14、文書19</td><td>「心魔劫」「法則関」「本源障」などの異なるタイプのボトルネックと、対応する突破の道筋を設定し、修練過程の階層感を高めることができる</td></tr><tr><td>E08</td><td>特殊体質と体系の適合</td><td>各種の特殊体質（先天道体、元素親和体、意識強感器など）と異なる修練体系との適合関係を設定する</td><td>文書12、文書51</td><td>「体質-体系適合マトリックス」を設計し、創作者がある体質がどの体系の修練に適しているかを迅速に判断できるようにすることができる</td></tr><tr><td>E09</td><td>修練資源の詳細分類</td><td>修練に必要な各種資源（天材地宝、エネルギー結晶、法則の欠片など）を詳細に分類・設定する</td><td>文書18、文書65</td><td>資源の等級、産地、採集方法、保存方法、使用のタブーなどを設定し、完全な修練資源エコシステムを構築することができる</td></tr></tbody></table><h2 id="_4-社会制度の拡張方向" tabindex="-1">4. 社会制度の拡張方向 <a class="header-anchor" href="#_4-社会制度の拡張方向" aria-label="Permalink to &quot;4. 社会制度の拡張方向&quot;">​</a></h2><table tabindex="0"><thead><tr><th>番号</th><th>拡張方向</th><th>拡張の価値</th><th>関連設定</th><th>創作提案</th></tr></thead><tbody><tr><td>E10</td><td>五种分型の具体的な社会形態</td><td>五种の共生文明分型のそれぞれの具体的な社会制度、経済モデル、文化的特徴を詳細に展開する</td><td>文書30-35</td><td>各分型に典型的な都市形態、家族構造、教育モデル、祝祭行事などを設定し、五种分型をそれぞれ特徴的にすることができる</td></tr><tr><td>E11</td><td>共生都市の計画と建設</td><td>共生文明における都市の計画理念、建築様式、インフラストラクチャ、機能分区を設定する</td><td>文書39、文書60</td><td>「垂直共生都市」「生態ネスト都市」「空間折り畳み都市」などの異なるタイプの都市形態を設計することができる</td></tr><tr><td>E12</td><td>教育体系の詳細な運営</td><td>就学前教育から高等教育、修練教育までの共生教育体系の完全な運営メカニズムを詳細に設定する</td><td>文書37、文書43</td><td>カリキュラム体系、考課方式、導師制度、異種族教育方案などを設定することができる</td></tr><tr><td>E13</td><td>医療体系の詳細な運営</td><td>通常医療と修練医療の結合を含む共生医療体系の運営メカニズムを詳細に設定する</td><td>文書38、文書44</td><td>病院体系、医療保険の償還プロセス、修練治療の特殊規範、異種族医療方案などを設定することができる</td></tr><tr><td>E14</td><td>社会保障と福祉体系</td><td>養老、失業、救助などを含む共生文明の社会保障体系を詳細に設定する</td><td>文書32、文書08</td><td>福祉の受給条件、給付基準、資金調達源、監督メカニズムなどを設定することができる</td></tr></tbody></table><h2 id="_5-法律とガバナンスの拡張方向" tabindex="-1">5. 法律とガバナンスの拡張方向 <a class="header-anchor" href="#_5-法律とガバナンスの拡張方向" aria-label="Permalink to &quot;5. 法律とガバナンスの拡張方向&quot;">​</a></h2><table tabindex="0"><thead><tr><th>番号</th><th>拡張方向</th><th>拡張の価値</th><th>関連設定</th><th>創作提案</th></tr></thead><tbody><tr><td>E15</td><td>典型的な法律事例</td><td>共生法院が審理した典型的な事例を作成し、実際における法律の適用を示す</td><td>文書40-49、文書92</td><td>「修練資源独占案」「異位面汚染賠償案」「暗黒置換体権利案」などの代表的な事例を作成することができる</td></tr><tr><td>E16</td><td>地方自治制度</td><td>憲法の枠組み内における各星域、各位面の自治制度と権限の区分を詳細に設定する</td><td>文書40、文書49</td><td>異なる自治単位の自治モデル、中央政府との関係、自治条例の制定プロセスなどを設定することができる</td></tr><tr><td>E17</td><td>選挙と民主制度</td><td>アンカー議事会代表の選挙制度と民主的意思決定メカニズムを詳細に設定する</td><td>文書32、文書49</td><td>選挙区の区分、候補者の資格、選挙プロセス、投票方式、任期制度などを設定することができる</td></tr><tr><td>E18</td><td>法律執行メカニズム</td><td>法律執行機関、執行プロセス、強制措置を含む法律の執行メカニズムを詳細に設定する</td><td>文書48、文書49</td><td>法律執行機関の組織構造、執行権限、執行プロセス、監督メカニズムなどを設定することができる</td></tr></tbody></table><h2 id="_6-生命と種族の拡張方向" tabindex="-1">6. 生命と種族の拡張方向 <a class="header-anchor" href="#_6-生命と種族の拡張方向" aria-label="Permalink to &quot;6. 生命と種族の拡張方向&quot;">​</a></h2><table tabindex="0"><thead><tr><th>番号</th><th>拡張方向</th><th>拡張の価値</th><th>関連設定</th><th>創作提案</th></tr></thead><tbody><tr><td>E19</td><td>単一種族の詳細設定</td><td>万族名録の中のある種族を詳細に展開し、生理的特徴、社会構造、文化的伝統、歴史的変遷を含める</td><td>文書50-52、文書94</td><td>龍族、精霊族、機械族、意識体族などの特徴的な種族を優先的に展開することを推奨する。各報族には言語、宗教、芸術、習俗などを含めることができる</td></tr><tr><td>E20</td><td>奇特生命の具体的な事例</td><td>具体的な奇特生命の個体または族群を設定し、三類の処置フローの実際の適用を示す</td><td>文書53-54</td><td>「虚空漂流者」「時間欠片生命」「法則寄生体」などの奇特生命の事例を設定することができる</td></tr><tr><td>E21</td><td>奇异エネルギーの具体的なタイプ</td><td>各種の奇异エネルギーの特性、出所、用途、管理方法を詳細に設定する</td><td>文書55-56</td><td>「因果エネルギー」「意識エネルギー」「時間残響エネルギー」などの奇异エネルギーのタイプを設定することができる</td></tr><tr><td>E22</td><td>暗黒置換体の具体的な事例</td><td>具体的な暗黒置換体の個体の物語を設定し、双魂倫理と四類の分支処置の実際の適用を示す</td><td>文書57-59</td><td>異なるタイプの暗黒置換体の事例の物語を作成し、双魂共存の倫理的ジレンマを探求することができる</td></tr><tr><td>E23</td><td>異種族融合の子孫</td><td>異なる種族間の通婚によって生まれた混合種族の特徴と文化を設定する</td><td>文書52、文書77</td><td>「半精霊」「龍人」「機械生化人」などの混合種族を設定し、そのアイデンティティと文化融合を探求することができる</td></tr></tbody></table><h2 id="_7-技術とエネルギーの拡張方向" tabindex="-1">7. 技術とエネルギーの拡張方向 <a class="header-anchor" href="#_7-技術とエネルギーの拡張方向" aria-label="Permalink to &quot;7. 技術とエネルギーの拡張方向&quot;">​</a></h2><table tabindex="0"><thead><tr><th>番号</th><th>拡張方向</th><th>拡張の価値</th><th>関連設定</th><th>創作提案</th></tr></thead><tbody><tr><td>E24</td><td>単一技術の詳細な原理</td><td>複製鏡、隔離空間、倍增果実のエンジニアリング化などの鍵となる技術の原理を詳細に解析する</td><td>文書60-69、文書63-64</td><td>技術の発展の歴史、コアコンポーネント、ワークフロー、技術的限界、アップグレードの方向性などを設定することができる</td></tr><tr><td>E25</td><td>修練器械の詳細分類</td><td>各種の修練補助器械の分類、機能、等級、使用方法を設定する</td><td>文書61、文書67</td><td>「修練舱」「法則検測儀」「エネルギー転換器」「意識増幅器」などの器械のタイプを設定することができる</td></tr><tr><td>E26</td><td>アンカーハードウェアの詳細設定</td><td>アンカーハードウェア施設の構造、機能、建設と保守を詳細に設定する</td><td>文書20、文書67</td><td>人工アンカーのコアコンポーネント、エネルギー供給、保守周期、故障処理などを設定することができる</td></tr><tr><td>E27</td><td>異位面通信技術</td><td>異位面通信の技術原理、デバイスのタイプ、通信プロトコルとセキュリティメカニズムを詳細に設定する</td><td>文書66、文書81</td><td>「アンカー波通信」「空間折り畳み通信」「意識共振通信」などの異なる通信方式を設定することができる</td></tr></tbody></table><h2 id="_8-歴史と事件の拡張方向" tabindex="-1">8. 歴史と事件の拡張方向 <a class="header-anchor" href="#_8-歴史と事件の拡張方向" aria-label="Permalink to &quot;8. 歴史と事件の拡張方向&quot;">​</a></h2><table tabindex="0"><thead><tr><th>番号</th><th>拡張方向</th><th>拡張の価値</th><th>関連設定</th><th>創作提案</th></tr></thead><tbody><tr><td>E28</td><td>重大歴史事件の詳細な記述</td><td>編年史の中のある重大事件の詳細な歴史的記述</td><td>文書70-79、文書93</td><td>「三百套体系開放事件」「20%活性化戦略の実施」「初回昇維マイルストーン」などの事件の全過程を詳細に記述することができる</td></tr><tr><td>E29</td><td>歴史人物の伝記</td><td>鍵となる人物の詳細な伝記を作成し、歴史の人文的深みを豊かにする</td><td>文書95</td><td>「玄衡子」「共生子」「立宪公」「三百師」などの鍵となる人物の伝記を作成することができる</td></tr><tr><td>E30</td><td>歴史の転換点の仮説分析</td><td>ある歴史事件が異なる方向に進んだ場合、共生文明の発展がどのように異なるかを分析する</td><td>文書70-79</td><td>「もし共生憲法が可決されなかったら」「もし20%活性化戦略が失敗したら」などの仮説分析を行い、歴史の偶然性を示すことができる</td></tr><tr><td>E31</td><td>考古学的発見の詳細記録</td><td>ある異位面考古学の詳細な発見と研究成果を設定する</td><td>文書84-87</td><td>「ある失われた文明の考古学的発見」「ある鍵となる歴史ノードの時間回溯考古学の成果」などを設定することができる</td></tr></tbody></table><h2 id="_9-異位面と時間の拡張方向" tabindex="-1">9. 異位面と時間の拡張方向 <a class="header-anchor" href="#_9-異位面と時間の拡張方向" aria-label="Permalink to &quot;9. 異位面と時間の拡張方向&quot;">​</a></h2><table tabindex="0"><thead><tr><th>番号</th><th>拡張方向</th><th>拡張の価値</th><th>関連設定</th><th>創作提案</th></tr></thead><tbody><tr><td>E32</td><td>具体的な位面の詳細設定</td><td>ある具体的な位面の法則パラメータ、文明形態、地理環境と歴史を設定する</td><td>文書80、文書81</td><td>「高魔位面」「科技位面」「蛮荒位面」「意識位面」などの異なるタイプの具体的な位面を設定することができる</td></tr><tr><td>E33</td><td>異位面外交事例</td><td>共生文明と他の位面文明が外交関係を樹立した具体的な事例を設定する</td><td>文書81、文書88</td><td>初回接触、国交交渉、文化交流、貿易協定などの具体的な外交事件を設定することができる</td></tr><tr><td>E34</td><td>時間回溯の具体的な事例</td><td>ある時間回溯操作の具体的なプロセス、発見と影響を設定する</td><td>文書82-83、文書89</td><td>「ある歴史的謎の回溯解読」「ある絶滅文明の回溯復元」などの事例を設定することができる</td></tr><tr><td>E35</td><td>時間パラドックス事件の詳細記録</td><td>ある時間パラドックス事件の発生、緊急対応と因果修復の全過程を設定する</td><td>文書89</td><td>小規模なパラドックス事件の完全な処置記録を作成し、予防・制御メカニズムの実際の運用を示すことができる</td></tr><tr><td>E36</td><td>異位面紛争と解決</td><td>共生文明と他の位面文明との間の紛争とその平和的解決プロセスを設定する</td><td>文書81、文書88</td><td>資源紛争、文化衝突、境界紛争などの異なるタイプの異位面紛争の事例を設定することができる</td></tr></tbody></table><h2 id="_10-拡張設定の創作原則" tabindex="-1">10. 拡張設定の創作原則 <a class="header-anchor" href="#_10-拡張設定の創作原則" aria-label="Permalink to &quot;10. 拡張設定の創作原則&quot;">​</a></h2><p>拡張設定の創作を行う際には、以下の原則に従うべきである:</p><ol><li><strong>一貫性を優先</strong>: すべての拡張設定は既存の設定と論理的に一貫性を保たなければならず、設定矛盾自己チェック表の検査に合格しなければならない。</li><li><strong>現実を基とする</strong>: 拡張設定は客観的法則に基づいて合理的に推演すべきであり、純粋な空想と設定の崩壊を避けるべきである。</li><li><strong>共生の立場</strong>: 拡張設定は常に反略奪、共生を提唱するという核心的立場を堅持しなければならず、略奪的行為を弁護してはならない。</li><li><strong>開放性</strong>: 拡張設定は一定の開放性を保ち、今後のさらなる拡張のためのスペースを残すべきである。</li><li><strong>実用性</strong>: 拡張設定は実際の創作価値を持つべきであり、物語の創作、ゲームデザイン、理論的討論に有用な素材を提供できるものでなければならない。</li></ol><h2 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to &quot;結語&quot;">​</a></h2><p>拡張設定提案リストは、アンカー共生文明設定体系の「開かれた扉」である。これは、この設定体系が閉じた完成形の製品ではなく、絶えず成長し、絶えず豊かになる生きた体系であることを示している。三十六の拡張方向はあくまで出発点に過ぎず、真の設定創造力は各参加者の想像力と情熱から生まれる。設定の一貫性という基本原則に従う限り、すべての価値のある拡張はアンカー共生文明の壮大な物語の中で不可欠な一部となるだろう。</p><h2 id="関連文書" tabindex="-1">関連文書 <a class="header-anchor" href="#関連文書" aria-label="Permalink to &quot;関連文書&quot;">​</a></h2><ul><li>97-設定矛盾自己チェック表</li><li>99-文書バージョンと保守説明</li><li>96-よくある質問FAQ</li></ul>',27)])])}const E=d(e,[["render",o]]);export{c as __pageData,E as default};
